--liquibase formatted sql
--changeset Swetha.H:HISTORYS_DDL_05 splitStatements:false
--preconditions onFail:HALT onError:HALT

CREATE OR REPLACE EDITIONABLE PROCEDURE ARCHIVE_INSTANCE_TABLES_BACATALOGS (
op_msg OUT VARCHAR2
)
AS
--l_errno    number;
--l_msg    varchar2(4000);
--l_idx    number;
pei_instance_id number;
pei_lca_id number;
g_n_execution_id_seq number;
v_limit NUMBER:='10000';
ln_errors NUMBER;
l_vc_enable_flag ARCHIVAL_TABLE_CONFIG.is_active%TYPE;
dml_errors EXCEPTION;
CURSOR pei_ver_del IS select instance_id,lca_id from(
 select pei.instance_id,lca.LCA_STATUS,lca.LCA_VERSION,lca.lca_id,dense_rank ()over(partition by  lca.entity_id order by lca.LCA_VERSION desc)rk from product_entity_instance pei,       
life_cycle_activity lca where lca.entity_id = pei.instance_id  --and lca.LCA_STATUS='Completed' 
and  pei.instance_id=1808936107) where rk<>1;
CURSOR sgp_ver_del IS select instance_id,lca_id,entity_id from(
 select sgp.instance_id,lca.LCA_STATUS,lca.LCA_VERSION,lca.lca_id,sgp.entity_id,dense_rank ()over(partition by  sgp.entity_id order by sgp.VERSION desc)rk 
from product_entity_instance pei,  service_group_parameter sgp,
life_cycle_activity lca where pei.instance_id=sgp.entity_id and lca.entity_id = sgp.instance_id  --and lca.LCA_STATUS='Completed' 
and sgp.entity_id in (Select instance_id from product_entity_instance pee, life_cycle_activity lcc where 
 lcc.entity_id = pee.instance_id 
and  pei.instance_id=1808936107)) where rk<>1;-- and LCA_STATUS='Completed';


PRAGMA exception_init ( dml_errors, -24381 );
--NUMBER v_limit IS v_limit;
--NUMBER ln_errors IS ln_errors;
--ARCHIVAL_TABLE_CONFIG.is_active%TYPE l_vc_enable_flag IS l_vc_enable_flag;
--EXCEPTION dml_errors IS dml_errors;
TYPE brecord1 IS TABLE OF sgp_ver_del%rowtype;

TYPE brecord IS TABLE OF pei_ver_del%rowtype;
brec1 brecord1;
brec brecord;


BEGIN
insert into stg_temp_archive_data  (instance_id,status,created_date,schema_name)
select instance_id,'Pending',systimestamp,'BACATALOG' from(
 select sgp.instance_id,lca.LCA_STATUS,lca.LCA_VERSION,lca.lca_id,dense_rank ()over(partition by  sgp.entity_id order by sgp.VERSION desc)rk 
from product_entity_instance pei,  service_group_parameter sgp,
life_cycle_activity lca where pei.instance_id=sgp.entity_id and lca.entity_id = sgp.instance_id  --and lca.LCA_STATUS='Completed' 
and sgp.entity_id in (Select instance_id from product_entity_instance pee, life_cycle_activity lcc where 
 lcc.entity_id = pee.instance_id 
 and pei.instance_id=1808936078)) where rk<>1;




insert into stg_temp_archive_data (instance_id,status,created_date,schema_name)select instance_id,'Pending',systimestamp,'BACATALOG' from (select instance_id from(
 select pei.instance_id,lca.LCA_STATUS,lca.LCA_VERSION,lca_id,dense_rank ()over(partition by  lca.entity_id order by lca.LCA_VERSION desc)rk from product_entity_instance pei,       
life_cycle_activity lca where lca.entity_id = pei.instance_id  --and lca.LCA_STATUS='Completed' 
and  pei.instance_id=1808936078) where rk<>1 );--and LCA_STATUS='Completed');  


g_n_execution_id_seq  := INSTANCE_ARCHIVAL_GEN_ID_SEQ.nextval;

SELECT is_active INTO l_vc_enable_flag FROM ARCHIVAL_TABLE_CONFIG WHERE INSTANCE_TABLE_NAME = 'ARCH_SERVICE_GROUP_PARAMETER';

--begin
OPEN sgp_ver_del; 
LOOP            
FETCH sgp_ver_del BULK COLLECT INTO brec1 LIMIT v_limit;  
 EXIT WHEN brec1.COUNT = 0;

--begin
     OPEN pei_ver_del;   
     LOOP
     FETCH pei_ver_del BULK COLLECT INTO brec LIMIT v_limit;  
 EXIT WHEN brec.COUNT = 0;
 FORALL vloop IN 1..brec1.count --SAVE EXCEPTIONS
INSERT INTO ARCH_LIFE_CYCLE_ACTIVITY(LCA_ID,LCA_TYPE,LCA_DESCRIPTION,LCA_VERSION,LCA_STATUS,LCA_STATUS_DTM,LCA_LEVEL,LCA_PRIORITY,LCA_DEPENDENCY_DATE,LCA_CREATION_DTM,LCA_CREATED_BY,LCA_SCHEDULE,LCA_DISPLAY_ON_TIMELINE,LCA_PLAN_START_DTM,LCA_PLAN_END_DTM,LCA_ACTUAL_START_DTM,LCA_ACTUAL_END_DTM,LCA_POTENTIAL_START_DTM,LCA_POTENTIAL_END_DTM,LCA_DURATION_PLAN,LCA_DURATION_ACTUAL,LCA_THRESHOLD,LCA_THRESHOLD_REASON_CODE,LCA_THRESHOLD_DATE,LCA_MILESTONE,LCA_REASON_CODE,LCA_COLOR_CODE,LCA_LABEL_COUNT,LCA_BEHAVIOUR_CODE,CPC_LCA_ID,CPC_LCA_VERSION,LCA_PARENT_ID,LCA_CHILD_ID,LCA_ROOT_ID,LCA_EXTERNAL_SOURCE_ID,LCA_NAME,LCA_COMPLETION_PERCENTAGE,LCA_MILESTONE_DTM,LCA_MODIFIED_BY,LCA_MODIFIED_ON,LCA_OWNER,ENTITY_SEQ,ENTITY_ID,ENTITY_NAME,LCA_ACTIVITY_REASON,LCA_ACTIVITY,VERSION,LIFE_CYCLE_ID,LCA_USERID,STANDARD_AGE,GRACE_AGE,CRITICAL_AGE,TYPE,CATEGORY,COMMENTS,REJECT_REASON,REJECT_DESCRIPTION,JEOPARDY_DESCRIPTION,JEOPARDY_CODE,RECALL_REASON,USER_GROUP,LCA_RULE_ID,LCA_RULE_STATUS,META_DATA_LIFECYCLEID,BUSINESS_ENTITY_TYPE,METADATA_VERSION)SELECT LCA.LCA_ID,LCA.LCA_TYPE,LCA.LCA_DESCRIPTION,LCA.LCA_VERSION,LCA.LCA_STATUS,LCA.LCA_STATUS_DTM,LCA.LCA_LEVEL,LCA.LCA_PRIORITY,LCA.LCA_DEPENDENCY_DATE,LCA.LCA_CREATION_DTM,LCA.LCA_CREATED_BY,LCA.LCA_SCHEDULE,LCA.LCA_DISPLAY_ON_TIMELINE,LCA.LCA_PLAN_START_DTM,LCA.LCA_PLAN_END_DTM,LCA.LCA_ACTUAL_START_DTM,LCA.LCA_ACTUAL_END_DTM,LCA.LCA_POTENTIAL_START_DTM,LCA.LCA_POTENTIAL_END_DTM,LCA.LCA_DURATION_PLAN,LCA.LCA_DURATION_ACTUAL,LCA.LCA_THRESHOLD,LCA.LCA_THRESHOLD_REASON_CODE,LCA.LCA_THRESHOLD_DATE,LCA.LCA_MILESTONE,LCA.LCA_REASON_CODE,LCA.LCA_COLOR_CODE,LCA.LCA_LABEL_COUNT,LCA.LCA_BEHAVIOUR_CODE,LCA.CPC_LCA_ID,LCA.CPC_LCA_VERSION,LCA.LCA_PARENT_ID,LCA.LCA_CHILD_ID,LCA.LCA_ROOT_ID,LCA.LCA_EXTERNAL_SOURCE_ID,LCA.LCA_NAME,LCA.LCA_COMPLETION_PERCENTAGE,LCA.LCA_MILESTONE_DTM,LCA.LCA_MODIFIED_BY,LCA.LCA_MODIFIED_ON,LCA.LCA_OWNER,LCA.ENTITY_SEQ,LCA.ENTITY_ID,LCA.ENTITY_NAME,LCA.LCA_ACTIVITY_REASON,LCA.LCA_ACTIVITY,LCA.VERSION,LCA.LIFE_CYCLE_ID,LCA.LCA_USERID,LCA.STANDARD_AGE,LCA.GRACE_AGE,LCA.CRITICAL_AGE,LCA.TYPE,LCA.CATEGORY,LCA.COMMENTS,LCA.REJECT_REASON,LCA.REJECT_DESCRIPTION,LCA.JEOPARDY_DESCRIPTION,LCA.JEOPARDY_CODE,LCA.RECALL_REASON,LCA.USER_GROUP,LCA.LCA_RULE_ID,LCA.LCA_RULE_STATUS,LCA.META_DATA_LIFECYCLEID,LCA.BUSINESS_ENTITY_TYPE,LCA.METADATA_VERSION  FROM LIFE_CYCLE_ACTIVITY  LCA where entity_id  =brec1(vloop).instance_id and lca_id=brec1(vloop).LCA_ID;
--DBMS_OUTPUT.PUT_LINE( ' lca inert '||brec1(vloop).LCA_ID);

FORALL vloop IN 1..brec1.count --SAVE EXCEPTIONS
