--changeset Swetha.H:HISTORYS_DDL_05_02 splitStatements:false
--preconditions onFail:HALT onError:HALT

create or replace PROCEDURE PROC_APPLICATION_ERROR_LOG(
ip_entity_id number,
ip_error_code varchar2,
ip_error_msg clob,
ip_app_name varchar2,
ip_created_by varchar2
)
AS PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
INSERT INTO app_error_log (
     ERROR_LOG_ID,                
     ENTITY_ID ,                    
     ERROR_CODE ,          
     ERROR_MSG  ,          
     APP_NAME   ,            
     ERROR_LOG_TIME,         
     CREATED_BY  ,           
     CREATED_DATE ,           
     MODIFIED_BY   ,        
     MODIFIED_DATE
     ) VALUES
     (
     ERROR_LOG_ID_SEQ.NEXTVAL,
     ip_entity_id,
     ip_error_code,
     ip_error_msg,
     ip_app_name,
     systimestamp,
     ip_created_by,
     systimestamp,
     null,
     null
     );
COMMIT;
END PROC_APPLICATION_ERROR_LOG;

